SELECT 
FROM MARKETING_CUSTOMER_TAG_IMPORT_BATCH

    record_status = 'ACTIVE'

      AND (batch_no LIKE CONCAT('%', #{keyword}, '%')
           OR source_file_name LIKE CONCAT('%', #{keyword}, '%')
           OR tag_name_snapshot LIKE CONCAT('%', #{keyword}, '%'))

    AND tag_id = #{tagId}
    AND status = #{status}
    AND import_emp_id = #{importEmpId}

ORDER BY import_time DESC, id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(1)
FROM MARKETING_CUSTOMER_TAG_IMPORT_BATCH

    record_status = 'ACTIVE'

      AND (batch_no LIKE CONCAT('%', #{keyword}, '%')
           OR source_file_name LIKE CONCAT('%', #{keyword}, '%')
           OR tag_name_snapshot LIKE CONCAT('%', #{keyword}, '%'))

    AND tag_id = #{tagId}
    AND status = #{status}
    AND import_emp_id = #{importEmpId}
